(298, 'documents', 'created', 'App\\Models\\Document', '01kqs0h3853xggmp7ba8ff6q0z', 'created', 'App\\Models\\User', '01kpb4njr44rav03q99e0nzyx1', '{\"attributes\":{\"user_id\":\"01kpb4njr44rav03q99e0nzyx1\",\"period_id\":\"01kpwcaagwv26qzran35c1m8tt\",\"type\":\"weekly_report\",\"title\":\"Weekly Report - Week 18\",\"state\":\"draft\",\"month\":null,\"year\":null,\"main_target\":null,\"target_accomplished\":0,\"target_explanation\":\"The weekly target was not fully accomplished because priority was redirected toward urgent improvements within the competition registration system, which required more dedicated time than initially planned to ensure smooth functionality and user readiness.\\r\\n\\r\\nIn addition, the planned collaboration sessions for uploading platform content and the technical follow-up on Adilisha XR manufacturing were not fully conducted within the week, leading to partial completion of the broader target. These pending components have therefore been rescheduled for continuation in the coming week\",\"file_path\":null,\"original_filename\":null}}', NULL, '2026-05-04 15:08:59', '2026-05-04 15:08:59'),
(299, 'documents', 'updated', 'App\\Models\\Document', '01kqs0h3853xggmp7ba8ff6q0z', 'updated', 'App\\Models\\User', '01kpb4njr44rav03q99e0nzyx1', '{\"attributes\":{\"state\":\"submitted\"},\"old\":{\"state\":\"draft\"}}', NULL, '2026-05-04 15:09:18', '2026-05-04 15:09:18'),
