(301, 'documents', 'updated', 'App\\Models\\Document', '01kqrzvve7d8fvk0jmxxy1h4wq', 'updated', 'App\\Models\\User', '01kp8d6cq9hrr981q6ss702dpp', '{\"attributes\":{\"main_target\":\"1.Strengthening 46 clubs while supporting expansion to reach 200 STEM clubs through the Tanzania STEM innovation competition 2026.\\r\\n2.Kwimba visit for vuta mdogo project initiatives.\"},\"old\":{\"main_target\":\"This week will focus on strengthening STEM clubs\"}}', NULL, '2026-05-04 15:19:52', '2026-05-04 15:19:52'),
