('01kqrzvve7d8fvk0jmxxy1h4wq', '01kp8d6cq9hrr981q6ss702dpp', '01kqf5dw156fazepccgrw42kf8', 'weekly_plan', NULL, NULL, NULL, NULL, 'Weekly Plan - Week 19', NULL, NULL, '{\"objective\":{\"status\":\"In Progress\",\"reflection_progress\":\"1.Schools have started to register in the system for competition.\\r\\n2.Teachers have started to register students into the system.\"},\"planned_activities\":[{\"day\":\"Monday\",\"activity_uid\":\"01KQRZVVDGH3F45ES1AZN91YAG\",\"activity\":\"Visiting the Regional Education office to seek for permission to conduct workshop.\",\"location\":\"Field\",\"notes_inclusion\":\"Laters and other necessary documents to be prepared.\"},{\"day\":\"Tuesday\",\"activity_uid\":\"01KQS150CHTEDEH5TP3RE07P5T\",\"activity\":\"Facilitate CHOMOZA STEM club sessions.\",\"location\":\"Virtual\",\"notes_inclusion\":\"Projects and session to be prepared and uploaded into the system.\"},{\"day\":\"Wednesday\",\"activity_uid\":\"01KQS6R2H3PH1CE4EPC11HFWQM\",\"activity\":\"Meeting with Kwimba District officers for discussion on implementation of Vuta mdogo project, including mobilization of teachers.\",\"location\":\"Field\",\"notes_inclusion\":\"Discussion about the vuta mdogo project.\"},{\"day\":\"Thursday\",\"activity_uid\":\"01KQS6R2H3PH1CE4EPC11HFWQN\",\"activity\":\"Para teacher mobilization in Kwimba.\",\"location\":\"Field\",\"notes_inclusion\":\"Obtaining the number of youths who will take part on teaching the pupils\"},{\"day\":\"Friday\",\"activity_uid\":\"01KQS6R2H3PH1CE4EPC11HFWQP\",\"activity\":\"Para teacher mobilization in Kwimba.\",\"location\":\"Field\",\"notes_inclusion\":\"none\"},{\"day\":\"Saturday\",\"activity_uid\":\"01KQS6R2H3PH1CE4EPC11HFWQQ\",\"activity\":\"Saturday session facilitation and report preparation.\",\"location\":\"Office\",\"notes_inclusion\":\"none\"}],\"key_meetings\":[],\"budget\":[{\"item\":\"kwimba trip. Transport, meals and acomodation\",\"description_purpose\":\"Vuta mdogo project\",\"amount\":\"100,000\",\"budget_uid\":\"01KQS6R2H3PH1CE4EPC11HFWQR\"}]}', '1.Strengthening 46 clubs while supporting expansion to reach 200 STEM clubs through the Tanzania STEM innovation competition 2026.\r\n2.Kwimba visit for vuta mdogo project initiatives.', NULL, NULL, 'draft', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-04 14:57:23', '2026-05-11 15:54:26', NULL),
('01kqs0h3853xggmp7ba8ff6q0z', '01kpb4njr44rav03q99e0nzyx1', '01kpwcaagwv26qzran35c1m8tt', 'weekly_report', NULL, NULL, NULL, NULL, 'Weekly Report - Week 18', NULL, NULL, '{\"summary\":\"This week focused primarily on improving and strengthening the competition registration system within the Adilisha STEM Labs platform. Key attention was given to reviewing the registration flow, identifying user-experience gaps, and implementing adjustments to make the process smoother and more effective for student participation.\\r\\n\\r\\nAlthough the original weekly target also included platform content upload and Adilisha XR manufacturing follow-up, these activities were only partially initiated and will continue into the following week due to limited time availability and the need to prioritize urgent platform functionality improvements.\",\"activity_progress\":[{\"activity_output\":\"Tuesday - Upload 40 experiments to the platform\",\"off_plan_activity\":\"\",\"progress\":\"Not started\",\"remarks_challenges\":null,\"next_step\":null,\"carry_to_next_plan\":true},{\"activity_output\":\"Wednesday - Continue facilitations of experiments uploads\",\"off_plan_activity\":\"\",\"progress\":\"Not started\",\"remarks_challenges\":null,\"next_step\":null,\"carry_to_next_plan\":true},{\"activity_output\":\"Thursday - Upload 10 projects to the platform\",\"off_plan_activity\":\"\",\"progress\":\"Not started\",\"remarks_challenges\":null,\"next_step\":null,\"carry_to_next_plan\":true},{\"activity_output\":\"Monday - Plan content upload structure with Programs team\",\"off_plan_activity\":\"\",\"progress\":\"Not started\",\"remarks_challenges\":null,\"next_step\":null,\"carry_to_next_plan\":true},{\"activity_output\":\"Friday - Evaluation and Improvement of competition panel side of the Adilisha STEM labs to address challenges that might happen\",\"off_plan_activity\":\"\",\"progress\":\"Done\",\"remarks_challenges\":null,\"next_step\":null,\"carry_to_next_plan\":false}],\"key_achievements\":[\"Successfully reviewed and strengthened the competition registration flow on the Adilisha STEM Labs platform.\",\"Improved user navigation and registration experience to support easier student onboarding into competitions.\"],\"challenges_mitigation\":[{\"challenge\":\"Time was disrupted due to the mixed timetable of mid week staff training\",\"action_taken_planned\":\"Holding most of activities to week 19\"}],\"budget_statuses\":[],\"target_accomplished_status\":\"partially_completed\"}', NULL, 0, 'The weekly target was not fully accomplished because priority was redirected toward urgent improvements within the competition registration system, which required more dedicated time than initially planned to ensure smooth functionality and user readiness.\r\n\r\nIn addition, the planned collaboration sessions for uploading platform content and the technical follow-up on Adilisha XR manufacturing were not fully conducted within the week, leading to partial completion of the broader target. These pending components have therefore been rescheduled for continuation in the coming week', 'draft', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-04 15:08:59', '2026-05-11 15:54:26', NULL),
('01kqs0t8kf3akcg8bj52kx5w1c', '01kpb4njr44rav03q99e0nzyx1', '01kqf5dw156fazepccgrw42kf8', 'weekly_plan', NULL, NULL, NULL, NULL, 'Weekly Plan - Week 19', NULL, NULL, '{\"objective\":{\"status\":\"Carried\",\"reflection_progress\":\"Expected progress includes successful completion of STEM content uploads onto the Adilisha STEM Labs platform, continued improvement of the competition system for better user experience, clear follow-up on Adilisha XR manufacturing progress and technical requirements to support timely implementation, and effective onboarding of the new STEM Labs Coordinator through orientation on lab equipment, systems, and ongoing technical operations.\"},\"planned_activities\":[{\"day\":\"Monday\",\"activity_uid\":\"01KQS0T8JMQ8TN034SBFHXV1CF\",\"activity\":\"Provide onboarding support to the newly joined STEM Labs Coordinator through guided orientation on STEM lab spaces, available equipment, operational systems, and ongoing technical activities, while introducing key workflows and current implementation areas within the STEM Labs program.\",\"location\":\"Office\",\"team_member_ids\":[\"01kpdrfj9wgpzb4ymkaegpq198\",\"01kpb4njr44rav03q99e0nzyx1\"],\"notes_inclusion\":\"This activity will involve physical walkthroughs of STEM lab facilities, introduction to laboratory equipment and their uses, explanation of current platform and technical projects being handled, and general familiarization with operational procedures to support smooth transition into the coordinator role\"},{\"day\":\"Tuesday\",\"activity_uid\":\"01KQS2B29CZHW800NG1EP278EJ\",\"activity\":\"Upload 40 experiments to the platform\",\"location\":\"Office\",\"team_member_ids\":[\"01kpdrfj9wgpzb4ymkaegpq198\",\"01kp8dnv9jvdzfnxcdkbbx5e1r\",\"01kpb4njr44rav03q99e0nzyx1\",\"01kp8cy0tm6n7vdrp9ykd0jhkc\",\"01kp8d6cq9hrr981q6ss702dpp\",\"01kp8dffx465w432484x6p18c8\",\"01kp8d2dth9g75wac55dvtexg0\",\"01kp8dj20nb8n15v8j2w4wdh6m\",\"01kpb51c9pcr257b9cwpmjj1qg\"],\"notes_inclusion\":\"Carried from weekly report: Not started\"},{\"day\":\"Wednesday\",\"activity_uid\":\"01KQS2B29CZHW800NG1EP278EK\",\"activity\":\"Continue facilitations of experiments uploads\",\"location\":\"Office\",\"team_member_ids\":[\"01kpdrfj9wgpzb4ymkaegpq198\",\"01kp8dnv9jvdzfnxcdkbbx5e1r\",\"01kpb4njr44rav03q99e0nzyx1\",\"01kp8cy0tm6n7vdrp9ykd0jhkc\",\"01kp8d6cq9hrr981q6ss702dpp\",\"01kp8dffx465w432484x6p18c8\",\"01kp8d2dth9g75wac55dvtexg0\",\"01kp8dj20nb8n15v8j2w4wdh6m\",\"01kpb51c9pcr257b9cwpmjj1qg\"],\"notes_inclusion\":\"Carried from weekly report: Not started\"},{\"day\":\"Thursday\",\"activity_uid\":\"01KQS2B29CZHW800NG1EP278EM\",\"activity\":\"Upload 10 projects to the platform\",\"location\":\"Office\",\"team_member_ids\":[\"01kpb4njr44rav03q99e0nzyx1\",\"01kp8d6cq9hrr981q6ss702dpp\",\"01kpb51c9pcr257b9cwpmjj1qg\"],\"notes_inclusion\":\"Carried from weekly report: Not started\"},{\"day\":\"Monday\",\"activity_uid\":\"01KQS2B29CZHW800NG1EP278EN\",\"activity\":\"Plan content upload structure with Programs team\",\"location\":\"Office\",\"team_member_ids\":[\"01kpb4njr44rav03q99e0nzyx1\",\"01kp8d6cq9hrr981q6ss702dpp\",\"01kpb51c9pcr257b9cwpmjj1qg\"],\"notes_inclusion\":\"Carried from weekly report: Not started\"}],\"key_meetings\":[{\"date\":\"2026-05-06\",\"meeting_uid\":\"01KQS257SSCTQ2QBPX8SA3WCTC\",\"meeting\":\"Dr. Nibu Virtual STEM labs meeting\",\"participant_user_ids\":[\"01kpdrfj9wgpzb4ymkaegpq198\",\"01kpb4njr44rav03q99e0nzyx1\",\"01kp8mdgyvgt8xwzmedfcyvmyw\"],\"location\":\"Virtual\",\"reactions_notes\":\"Implementation start meeting\"}],\"budget\":[]}', 'Completion of Platform Content Upload, Adilisha XR Manufacturing Technical Follow-up, and STEM Labs Coordinator Onboarding Support – Finalize the upload of experiments, projects, and weekly STEM club session materials onto the Adilisha STEM Labs platform in collaboration with the Programs team, continue refining the competition system based on registration flow improvements, conduct follow-up on manufacturing progress and