('01kr6eqe1phx6k52n6dm2gqk1b', '01kpb51c9pcr257b9cwpmjj1qg', '01kqf5dw156fazepccgrw42kf8', 'weekly_report', NULL, NULL, NULL, NULL, 'Weekly Report - Week 19', NULL, NULL, '{\"summary\":\"This week focused on advancing the organization\\u2019s fundraising efforts through the preparation and submission of multiple strategic proposals aligned with funding priorities.\\r\\n\\r\\nKey submissions included a competitive application to the .ORG Impact Awards, which recognizes organizations using digital platforms to create social impact globally, with potential funding of up to USD 50,000 and global visibility for selected finalists.\\r\\n\\r\\nAlso submitted a proposal under the Women in Digital Transformation initiative, which emphasizes Gender-Responsive Policies (GRP), inclusive digital transformation, AI governance, and multi-stakeholder collaboration at national and global levels.\\r\\n\\r\\nFurthermore, an application was successfully submitted for the Global Entrepreneurship Summit (GES) Awards, through STEMlabs, showcasing an XR (Extended Reality) product currently in the market. This opportunity recognizes innovative and scalable solutions with strong impact potential.\",\"activity_progress\":[{\"activity_output\":\"Friday - Identify at least 3  donors aligned with STEM and gender\",\"off_plan_activity\":\"\",\"progress\":\"Done\",\"remarks_challenges\":\"UNICEF,UNESCO and Together Women Rise were identified\",\"next_step\":\"Conduct meeting for collaboration\",\"carry_to_next_plan\":false},{\"activity_output\":\"Thursday - Develop draft for VVOB proposal\",\"off_plan_activity\":\"\",\"progress\":\"In progress\",\"remarks_challenges\":\"Being discussed with our partner MUCE\",\"next_step\":\"Followup with MUCE\",\"carry_to_next_plan\":false},{\"activity_output\":\"Wednesday - Compile and attach documents for submission, The community centered connectivity grant concept note\",\"off_plan_activity\":\"\",\"progress\":\"Done\",\"remarks_challenges\":\"Alignned with proposal\",\"next_step\":\"Continue drafting other opportunity grant\",\"carry_to_next_plan\":false},{\"activity_output\":\"Tuesday - Develop fraft for Community Centered Connectivity Grant concept note\",\"off_plan_activity\":\"\",\"progress\":\"Done\",\"remarks_challenges\":\"Time constraints due to multiple submissions\",\"next_step\":\"Continue drafting other opportunity grant\",\"carry_to_next_plan\":false},{\"activity_output\":\"Monday - Develop draft for Women in Digital transformation concept note\",\"off_plan_activity\":\"\",\"progress\":\"Done\",\"remarks_challenges\":\"Submitted\",\"next_step\":\"Follow up\",\"carry_to_next_plan\":false}],\"key_meetings\":[{\"meeting_uid\":\"derived_5f8a2568dbb6aa273a1e\",\"location\":\"Virtual\",\"reactions_notes\":\"Requesting partnership\",\"date\":\"2026-05-08\",\"meeting\":\"External partner outreach\",\"participant_user_ids\":[\"01kpb51c9pcr257b9cwpmjj1qg\"],\"status\":\"Not done\"}],\"key_achievements\":[\"Developed and submitted four major competitive proposals aligned with global funding priorities.\"],\"challenges_mitigation\":[{\"challenge\":\"Tight deadlines for multiple proposals\",\"action_taken_planned\":\"Prioritized key opportunity grant\"}],\"budget_statuses\":[],\"target_accomplished_status\":\"completed\"}', NULL, 1, NULL, 'draft', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-05-09 20:27:15', '2026-05-11 15:54:26', NULL);
